import { writeFile } from 'node:fs/promises';
import path from 'node:path';

import { digestProposal, fingerprintRepository } from '../../agent-init/evaluation-harness.js';

// Recorded-contract test declarations, never imported by the production runner.
// The generated bytes below are an independent literal, not fixture.expected rendering.
export const NODE_SKILL = `---
name: build-verify
description: Run this repository's ordered lint and test checks when validating code changes.
---
## When to use
Validating a code change.
## When not to use
Read-only analysis that does not require repository validation.
## Workflow
Run pnpm lint, then pnpm test.
## Project-specific rules
Use this repository's declared pnpm workflow.
## Verification
pnpm lint && pnpm test
`;

const SKILL_SPECIMENS = {
  '03-node-pnpm': { name: 'build-verify', content: NODE_SKILL },
  '11-maven-multi-module-build-verify': { name: 'build-verify', content: `---
name: build-verify
description: Verify the API module and its upstream dependencies when validating changes to that module or its dependencies.
---
## When to use
Validating the API module or its dependencies.
## When not to use
An unrelated module with its own workflow.
## Workflow
Run mvn -pl services/api -am verify.
## Project-specific rules
Include upstream modules and preserve their descriptors.
## Verification
mvn -pl services/api -am verify
` },
  '12-flyway-database-migration': { name: 'database-migration', content: `---
name: database-migration
description: Create append-only schema migrations and run the documented migrate and validate checks when adding or validating a database migration.
---
## When to use
Adding or validating an append-only Flyway migration.
## When not to use
Application-only changes without a schema migration.
## Workflow
Inspect published history; add the next migration; use the documented migrate and validate checks only after separate execution authorization.
## Project-specific rules
Never edit published migrations.
## Verification
Check naming and append-only history, then the documented migrate and validate results. This synthetic test executes no database command.
` },
  '13-audit-log': { name: 'audit-log', content: `---
name: audit-log
description: Preserve actor, action, and resource audit events and run the audit contract test when adding or changing auditable domain operations.
---
## When to use
Adding or changing an auditable operation.
## When not to use
Operations outside the audit boundary.
## Workflow
Preserve actor, action and resource and verify the audit contract.
## Project-specific rules
Cross-check existing event call sites and required fields.
## Verification
Inspect required fields and the documented audit contract test result.
` },
  '15-deployment': { name: 'deployment', content: `---
name: deployment
description: Build, deploy, and smoke-test the application when deploying to the documented staging environment.
---
## When to use
An independently authorized staging deployment.
## When not to use
Production or infrastructure work without its own approved procedure.
## Workflow
Build, deploy to the documented staging environment, then inspect smoke verification. Each external action requires separate authorization.
## Project-specific rules
This synthetic test never accesses staging or deploys anything.
## Verification
Check the documented staging health result after an authorized deployment.
` },
};

export async function writeSyntheticSetup(root, cwd, fixture, mutate = () => {}) {
  const candidates = fixture.expected.skillDecisions.map(({ action, ...candidate }) => ({ ...structuredClone(candidate), decision: action }));
  const classes = new Map(fixture.expected.classifications.map((entry) => [entry.factId, entry]));
  const scopes = new Map();
  for (const fact of fixture.expected.facts) for (const id of fact.evidenceIds) scopes.set(id, classes.get(fact.id));
  const actions = [];
  const specimen = SKILL_SPECIMENS[fixture.id];
  if (specimen) {
    const candidate = candidates.find((entry) => entry.name === specimen.name);
    actions.push({
      id: fixture.id === '03-node-pnpm' ? 'synthetic-node-skill' : `synthetic-${specimen.name}-skill`,
      action: 'CREATE', kind: 'project-skill', target: `.agents/skills/${specimen.name}/SKILL.md`,
      reason: 'Explicit synthetic response specimen, not a real model-generated payload.', evidenceIds: [...candidate.evidenceIds],
      baselineFingerprint: 'missing', proposedContent: specimen.content, skillCandidate: candidate,
    });
  }
  const proposal = {
    type: 'proposal', id: `synthetic-${fixture.id}`, revision: 1, projectSummary: fixture.purpose,
    unknowns: [...fixture.expected.unknowns], warnings: [], nonGoals: [...fixture.expected.forbiddenPaths],
    validationPlan: ['physical scope and bytes', 'read-only second reconcile'], actions,
  };
  const fingerprint = await fingerprintRepository(cwd);
  const record = {
    schemaVersion: 1, fixtureId: fixture.id, harness: 'recorded-contract',
    evidenceLedger: fixture.evidence.map((entry) => ({
      ...structuredClone(entry), ...(scopes.get(entry.id) ?? { persistenceScope: 'Unknown', deterministicEnforcementCandidate: false, destination: null }),
    })),
    events: [
      { type: 'preflight', readOnly: true, baselineId: `synthetic-baseline-${fixture.id}`, git: { isRepository: false, staged: [], unstaged: [], untracked: [] }, existingAgentAssets: fixture.expected.detection.agentConfigPaths, repositoryFingerprintBefore: fingerprint },
      { type: 'explore', readOnly: true, strategy: ['search', 'read-relevant', 'cross-check'], sensitiveFiles: 'presence-only', repositoryFingerprintAfter: fingerprint },
      { type: 'profile', facts: structuredClone(fixture.expected.facts), unknowns: fixture.expected.unknowns.map((id) => ({ id })) },
      { type: 'classify', decisions: structuredClone(fixture.expected.classifications) },
      { type: 'skills', candidates }, proposal,
    ],
    externalAcceptance: { claudeCode: { status: 'not-run', evidence: null }, codex: { status: 'not-run', evidence: null } },
  };
  const scenario = {
    synthetic: true,
    proposal: { schemaVersion: 1, kind: 'setup-proposal', record, summary: { proposalId: proposal.id, revision: proposal.revision, actionIds: actions.map((entry) => entry.id) }, audit: { proposalDigest: digestProposal(proposal) } },
    validation: { schemaVersion: 1, kind: 'setup-validation', events: [{ type: 'validation', passed: true, changedPaths: [], forbiddenPathsChanged: [], preservationPassed: true, evidencePassed: true, singleSourcePassed: true, unknownsPreserved: true }] },
    reconcile: { schemaVersion: 1, kind: 'setup-reconcile', event: { type: 'reconcile', mode: 'dry-run', proposalActions: [], writes: [] } },
  };
  mutate(scenario);
  const file = path.join(root, `synthetic-${fixture.id}.json`);
  await writeFile(file, JSON.stringify(scenario), { flag: 'wx', mode: 0o600 });
  return file;
}

