export async function writeSyntheticRouting(root, routing) {
  const file = path.join(root, `synthetic-route-${routing.caseId}.json`);
  await writeFile(file, JSON.stringify({ synthetic: true, routing }), { flag: 'wx', mode: 0o600 });
  return file;
}
